#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // word to count
    std::string line; // current line

    // Ask user for input file name and word to count
    std::cout << "Enter input file name: ";
    std::string inputFile;
    std::cin >> inputFile;

    std::cout << "Enter word to count: ";
    std::cin >> wordToCount;

    // Open input file
    std::ifstream inputFileStream(inputFile);
    if (!inputFileStream) {
        std::cerr << "Error: Cannot open input file: " << inputFile << std::endl;
        return 1;
    }

    // Count word occurrences
    int wordCount = 0;
    while (std::getline(inputFileStream, line)) {
        // Convert line to lowercase for case-insensitive comparison
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);
        // Count word occurrences in line
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
            wordCount++;
            pos += wordToCount.length();
        }
    }

    // Close input file
    inputFileStream.close();

    // Display word count
    std::cout << "Number of occurrences of '" << wordToCount << "' in " << inputFile << ": " << wordCount << std::endl;

    return 0;
}
